const updateNodeLastSeen = `-- name: UpdateNodeLastSeen :execrows
UPDATE nodes
SET last_seen = $1
WHERE public_key = $2
  AND last_seen < $1
`

type UpdateNodeLastSeenParams struct {
	LastSeen  time.Time
	PublicKey string
}

func (q *Queries) UpdateNodeLastSeen(ctx context.Context, arg UpdateNodeLastSeenParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateNodeLastSeen, arg.LastSeen, arg.PublicKey)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateNodeMultibyteCaps = `-- name: UpdateNodeMultibyteCaps :execrows
WITH v AS (
    SELECT unnest($1::text[])  AS public_key,
           unnest($2::int[])      AS sup,
           unnest($3::text[]) AS evidence
)
UPDATE nodes n
SET multibyte_sup      = v.sup,
    multibyte_evidence = NULLIF(v.evidence, '')
FROM v
WHERE n.public_key = v.public_key
  AND n.multibyte_sup <= v.sup  -- never downgrade: confirmed (2) stays above suspected (1)
  AND (n.multibyte_sup, n.multibyte_evidence)
      IS DISTINCT FROM (v.sup, NULLIF(v.evidence, ''))
`

type UpdateNodeMultibyteCapsParams struct {
	Pubkeys  []string
	Sups     []int32
	Evidence []string
}

func (q *Queries) UpdateNodeMultibyteCaps(ctx context.Context, arg UpdateNodeMultibyteCapsParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateNodeMultibyteCaps, arg.Pubkeys, arg.Sups, arg.Evidence)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
